'use strict'

function read (stream, options, callback) {
  var done = callback
  if (typeof options === 'function') {
    done = options
  }
  if (done) {
    return readStream(stream, wrap(done))
  }
  return readStream(stream, function onRead (err, buf) {
    return [err, buf]
  })
}

function readStream (stream, callback) {
  function done () {
    var args = new Array(arguments.length)
    for (var i = 0; i < arguments.length; i++) {
      args[i] = arguments[i]
    }
    return invokeCallback()
    function invokeCallback () {
      callback.apply(null, args)
    }
  }
  return done(null, 'b')
}

function wrap (fn) {
  return fn.bind(null)
}

module.exports = read
